import React from 'react';
import { Input, Textarea, Select, Button, Checkbox } from '../ui';
import ImageUploadButton from '../ImageUploadButton';
import ProductModifiersPicker from './ProductModifiersPicker';
import useProductForm from '../../hooks/useProductForm';

/**
 * Formulario de crear/editar producto. Si recibe `product`, edita ese
 * producto (precargando sus datos y sus opciones); si no, crea uno nuevo.
 */
const ProductForm = ({ product, categories, allProducts, modifiers, onSaved }) => {
  const {
    form,
    setField,
    comboItems,
    toggleComboItem,
    setComboQty,
    modifierSelections,
    setModifierSelections,
    loadingExtras,
    handleSubmit,
  } = useProductForm(product, onSaved);

  const comboCandidates = allProducts.filter((p) => !product || p.id !== product.id);

  return (
    <form onSubmit={handleSubmit} className="grid grid-cols-2 gap-3">
      <Input
        type="text"
        placeholder="Nombre *"
        value={form.name}
        onChange={(e) => setField('name', e.target.value)}
        required
      />
      <Select value={form.category_id} onChange={(e) => setField('category_id', e.target.value)} required>
        <option value="">Categoría *</option>
        {categories.map((c) => (
          <option key={c.id} value={c.id}>
            {c.icon} {c.name}
          </option>
        ))}
      </Select>
      <Input
        type="number"
        step="0.01"
        placeholder="Precio *"
        value={form.price}
        onChange={(e) => setField('price', e.target.value)}
        required
      />
      <Input
        type="number"
        step="0.01"
        placeholder="Costo"
        value={form.cost}
        onChange={(e) => setField('cost', e.target.value)}
      />
      <Input
        type="number"
        placeholder="Tiempo (min)"
        value={form.preparation_time_min}
        onChange={(e) => setField('preparation_time_min', e.target.value)}
      />

      <div className="col-span-2">
        <ImageUploadButton value={form.image_url} onChange={(url) => setField('image_url', url)} label="Foto del plato" />
      </div>

      <Checkbox
        id="avail"
        checked={form.is_available}
        onChange={(e) => setField('is_available', e.target.checked)}
        label="Disponible"
      />
      <Checkbox
        id="isCombo"
        checked={form.is_combo}
        onChange={(e) => setField('is_combo', e.target.checked)}
        label="🍔 Es un combo/promoción"
      />

      {form.is_combo && (
        <div className="col-span-2 bg-slate-900 rounded-[10px] p-3.5">
          <p className="text-slate-400 text-xs mb-2.5">
            Elige qué productos incluye este combo y en qué cantidad:
          </p>
          <div className="flex flex-col gap-2 max-h-[220px] overflow-y-auto">
            {comboCandidates.map((p) => (
              <div key={p.id} className="flex items-center justify-between gap-2">
                <label className="flex items-center gap-2 flex-1 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={comboItems[p.id] !== undefined}
                    onChange={(e) => toggleComboItem(p.id, e.target.checked)}
                    className="w-4 h-4 accent-sky-400"
                  />
                  <span className="text-slate-200 text-[13px]">{p.name}</span>
                  <span className="text-slate-500 text-[11px]">${p.price?.toFixed(2)}</span>
                </label>
                {comboItems[p.id] !== undefined && (
                  <Input
                    type="number"
                    min="1"
                    className="w-[70px] px-2 py-1"
                    value={comboItems[p.id]}
                    onChange={(e) => setComboQty(p.id, e.target.value)}
                  />
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="col-span-2">
        <label className="block text-slate-400 text-xs mb-2">
          ⚙️ Opciones para este plato (ej: término de cocción, con/sin papas)
        </label>
        {loadingExtras ? (
          <p className="text-slate-500 text-xs">Cargando opciones del producto...</p>
        ) : (
          <ProductModifiersPicker
            allModifiers={modifiers}
            selections={modifierSelections}
            onChange={setModifierSelections}
          />
        )}
      </div>

      <Textarea
        placeholder="Descripción"
        value={form.description}
        onChange={(e) => setField('description', e.target.value)}
        className="col-span-2"
      />
      <Textarea
        placeholder="Historia"
        value={form.history}
        onChange={(e) => setField('history', e.target.value)}
        className="col-span-2"
      />
      <Textarea
        placeholder="Ingredientes"
        value={form.ingredients}
        onChange={(e) => setField('ingredients', e.target.value)}
        className="col-span-2"
      />

      <Button type="submit" variant="success" className="col-span-2">
        {product ? '💾 Guardar Cambios' : 'Crear Plato'}
      </Button>
    </form>
  );
};

export default ProductForm;
